(function(){
  const state={items:[],query:'',source:'',selected:null,loading:false,extraction:null,analysis:null};
  const SOURCE_LABEL={activity:'กิจกรรม',task:'มอบหมายงาน',graphic:'Graphic Production'};
  const SOURCE_ICON={activity:'ACT',task:'TASK',graphic:'GFX'};
  const fmtBytes=n=>!n?'-':n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;
  const itemKey=x=>`${x.source_kind}:${x.source_file_id}`;
  const selectedItem=()=>state.items.find(x=>itemKey(x)===state.selected)||null;
  const extOf=x=>(String(x.file_name||'').split('.').pop()||'').toLowerCase();
  function isSupported(x){return ['pdf','txt','csv','md','json','docx','xlsx'].includes(extOf(x))||/^(text\/|application\/pdf)/.test(x.mime_type||'');}
  function renderShell(){
    main.innerHTML=`${crumb('หน้าแรก','คลังไฟล์จากงาน')}<section class="filelib-hero"><div><h1>คลังไฟล์จากงาน</h1><p>ค้นหาไฟล์เหมือน Drive จากงานที่คุณมีสิทธิ์เท่านั้น ดึงข้อความและวิเคราะห์เมื่อคุณกดอนุญาตเป็นรายไฟล์</p></div><div class="filelib-privacy"><span>🔒 ตามสิทธิ์งาน</span><span>✋ ไม่ดึงข้อความอัตโนมัติ</span><span>🧠 ไม่ส่ง AI ภายนอก</span></div></section><section class="filelib-search"><div class="filelib-searchline"><input class="fin" id="filelib-q" value="${esc(state.query)}" placeholder="ค้นหาชื่อไฟล์ ชื่องาน แผนก หรือประเภทไฟล์" onkeydown="if(event.key==='Enter')fileLibrarySearch()"><select class="fin" id="filelib-source" onchange="fileLibrarySetSource(this.value)"><option value="">ทุกแหล่งงาน</option>${Object.entries(SOURCE_LABEL).map(([k,v])=>`<option value="${k}" ${state.source===k?'selected':''}>${v}</option>`).join('')}</select><button class="tbtn primary" onclick="fileLibrarySearch()">ค้นหา</button></div><div class="filelib-chips">${[['','ทั้งหมด'],['activity','กิจกรรม'],['task','มอบหมายงาน'],['graphic','Graphic Production']].map(([k,v])=>`<button class="filelib-chip ${state.source===k?'active':''}" onclick="fileLibrarySetSource('${k}')">${v}</button>`).join('')}</div></section><div class="filelib-layout"><section class="filelib-list" id="filelib-list"></section><aside class="filelib-panel" id="filelib-panel"></aside></div>`;
    renderList();renderPanel();
  }
  function renderList(){const host=document.getElementById('filelib-list');if(!host)return;
    if(state.loading){host.innerHTML='<div class="filelib-empty">กำลังค้นหาไฟล์ตามสิทธิ์ของคุณ…</div>';return;}
    host.innerHTML=`<div class="filelib-summary"><b>${nf(state.items.length)} ไฟล์ที่เข้าถึงได้</b><span class="filelib-note">ค้นจากข้อมูลกำกับเท่านั้น</span></div>${state.items.length?state.items.map(x=>`<article class="filelib-row ${state.selected===itemKey(x)?'active':''}" onclick="fileLibrarySelect('${itemKey(x)}')"><div class="filelib-icon">${SOURCE_ICON[x.source_kind]||'FILE'}</div><div><h3>${esc(x.file_name)}</h3><div class="filelib-meta"><span>${esc(x.work_title||'-')}</span><span>• ${esc(x.department_code||'-')}</span><span>• ${esc(x.file_kind||'-')}</span><span>• ${fmtBytes(x.size_bytes)}</span></div></div><span class="filelib-state ${x.extraction_status==='ready'?'ready':''}">${x.extraction_status==='ready'?'ดึงข้อความแล้ว':'ยังไม่ดึงข้อความ'}</span></article>`).join(''):'<div class="filelib-empty"><b>ไม่พบไฟล์</b><br>ลองเปลี่ยนคำค้นหรือแหล่งงาน</div>'}`;
  }
  function renderPanel(){const host=document.getElementById('filelib-panel');if(!host)return;const x=selectedItem();
    if(!x){host.innerHTML='<div class="filelib-empty">เลือกไฟล์เพื่อดูรายละเอียด<br>เปิดไฟล์ ดึงข้อความ หรือวิเคราะห์ตามหัวข้อ</div>';return;}
    const supported=x.can_extract&&isSupported(x);
    host.innerHTML=`<div class="filelib-panel-head"><span class="filelib-source">${SOURCE_ICON[x.source_kind]} ${esc(SOURCE_LABEL[x.source_kind])}</span><h2>${esc(x.file_name)}</h2><div class="filelib-note">${esc(x.work_title)} · ${esc(x.department_code||'-')} · ${fmtBytes(x.size_bytes)}</div></div><div class="filelib-panel-body"><div class="filelib-actions"><button class="tbtn primary" onclick="fileLibraryOpenFile(false)">เปิดไฟล์</button><button class="tbtn" onclick="fileLibraryOpenWork()">ไปที่งานต้นทาง</button></div><div class="filelib-consent"><b>ขั้นที่ 1 · คลังไฟล์</b><br>ตอนนี้ระบบอ่านเฉพาะชื่อไฟล์ ประเภท และงานต้นทาง ยังไม่ได้อ่านข้อความภายในไฟล์</div><div class="filelib-extract"><b>ขั้นที่ 2 · ดึงข้อความจากไฟล์</b><p class="filelib-note">ทำเฉพาะไฟล์นี้เมื่อคุณกดปุ่ม ข้อความจะเก็บใน Company Hub เพื่อให้ผู้มีสิทธิ์ในงานค้นและอ้างอิงได้</p><button class="tbtn ${supported?'primary':''}" ${supported?'':'disabled'} onclick="fileLibraryExtract()">${x.extraction_status==='ready'?'ดึงข้อความใหม่':'ดึงข้อความจากไฟล์'}</button>${!supported?`<p class="filelib-note">รองรับ PDF, DOCX, XLSX, TXT และ CSV · ลิงก์ภายนอก/รูปภาพยังเปิดดูได้แต่จะไม่ดึงอัตโนมัติ</p>`:''}<div id="filelib-extracted"></div></div><div class="filelib-extract"><b>ขั้นที่ 3 · วิเคราะห์ตามหัวข้อ</b><p class="filelib-note">ใช้กฎของระบบในเบราว์เซอร์ ไม่ส่งเนื้อหาไป AI ภายนอก และไม่เสียค่า API</p><select class="fin" id="filelib-topic-preset" onchange="fileLibraryPreset(this.value)"><option value="">เลือกหัวข้อแนะนำ</option><option>สรุปสาระสำคัญ</option><option>สรุปความเสี่ยง</option><option>ค้นหาตัวเลขสำคัญ</option><option>รายการที่ต้องดำเนินการต่อ</option></select><textarea class="fin" id="filelib-topic" placeholder="ระบุหัวข้อ เช่น สรุปความเสี่ยงด้านบัญชี"></textarea><button class="tbtn primary" style="margin-top:7px" onclick="fileLibraryAnalyze()">วิเคราะห์ไฟล์นี้</button><div id="filelib-analysis"></div></div></div>`;
    renderExtraction();renderAnalysis();
  }
  function renderExtraction(){const host=document.getElementById('filelib-extracted');if(!host||!state.extraction)return;const seg=state.extraction.segments||[];host.innerHTML=`<div class="filelib-result"><b>ดึงข้อความแล้ว ${nf(seg.length)} ส่วน</b><div class="filelib-preview">${esc(seg.slice(0,3).map(s=>`[${s.label}]\n${s.text}`).join('\n\n').slice(0,2200))}</div></div>`;}
  function renderAnalysis(){const host=document.getElementById('filelib-analysis');if(!host||!state.analysis)return;const x=selectedItem();host.innerHTML=`<div class="filelib-result"><b>${esc(state.analysis.topic)}</b><div class="filelib-answer">${state.analysis.items.map(a=>`<div class="filelib-answer-item">${esc(a.text)}<div class="filelib-cites">${a.citations.map(c=>`<button class="filelib-cite" onclick="fileLibraryOpenFile(false,${Number(c.page)||0})">${esc(x.file_name)} · ${esc(c.label)}</button>`).join('')}</div></div>`).join('')}</div><div class="filelib-actions"><button class="tbtn sm" onclick="fileLibraryOpenFile(false)">เปิดไฟล์ต้นฉบับ</button><button class="tbtn sm" onclick="fileLibraryOpenWork()">เปิดงานต้นทาง</button></div></div>`;}
  async function search(){state.query=document.getElementById('filelib-q')?.value.trim()||state.query;state.loading=true;renderList();try{const r=await SB.rpc('file_library_items',{p_query:state.query,p_source:state.source,p_limit:300,p_offset:0});if(r.error)throw r.error;state.items=r.data||[];if(state.selected&&!state.items.some(x=>itemKey(x)===state.selected))state.selected=null;}catch(e){state.items=[];toast('ค้นหาคลังไฟล์ไม่สำเร็จ · '+(e.message||e),'info');}finally{state.loading=false;renderList();renderPanel();}}
  async function signedUrl(x,download=false){if(x.external_url)return x.external_url;if(!x.storage_path)throw new Error('ไม่พบที่อยู่ไฟล์');const r=await SB.storage.from(x.bucket_name).createSignedUrl(x.storage_path,600,download?{download:x.file_name}:undefined);if(r.error)throw r.error;return r.data?.signedUrl||'';}
  async function getBuffer(x){if(!x.storage_path)throw new Error('ลิงก์ภายนอกไม่ถูกดึงข้อความอัตโนมัติ');const r=await SB.storage.from(x.bucket_name).download(x.storage_path);if(r.error)throw r.error;return await r.data.arrayBuffer();}
  const cleanText=s=>String(s||'').replace(/\u0000/g,'').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();
  async function extractPdf(buf){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(buf)}).promise;const out=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent(),text=cleanText(content.items.map(v=>v.str).join(' '));if(text)out.push({label:`หน้า ${i}`,page:i,text});}return out;}
  async function extractDocx(buf){const mod=await import('https://cdn.jsdelivr.net/npm/jszip@3.10.1/+esm'),JSZip=mod.default||mod;const zip=await JSZip.loadAsync(buf),xml=await zip.file('word/document.xml')?.async('text');if(!xml)throw new Error('ไม่พบเนื้อหาใน DOCX');const doc=new DOMParser().parseFromString(xml,'application/xml'),paras=[...doc.getElementsByTagNameNS('*','p')];return paras.map((p,i)=>({label:`ย่อหน้า ${i+1}`,page:0,text:cleanText([...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join(''))})).filter(x=>x.text);}
  async function extractXlsx(buf){const XLSX=await import('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/+esm'),book=XLSX.read(buf,{type:'array'}),out=[];for(const name of book.SheetNames){const rows=XLSX.utils.sheet_to_json(book.Sheets[name],{header:1,defval:''});rows.forEach((row,i)=>{const text=cleanText(row.join(' | '));if(text)out.push({label:`ชีต ${name} แถว ${i+1}`,page:0,text});});}return out;}
  async function extractItem(x){const buf=await getBuffer(x),ext=extOf(x);if(ext==='pdf'||x.mime_type==='application/pdf')return extractPdf(buf);if(ext==='docx')return extractDocx(buf);if(ext==='xlsx')return extractXlsx(buf);const text=cleanText(new TextDecoder('utf-8').decode(buf));return text.split(/\n{2,}/).map((v,i)=>({label:`ส่วน ${i+1}`,page:0,text:cleanText(v)})).filter(x=>x.text);}
  function tokens(s){return [...new Set(String(s||'').toLowerCase().match(/[\p{L}\p{N}]{2,}/gu)||[])];}
  function analyzeSegments(topic,segments){const lower=topic.toLowerCase(),risk=['เสี่ยง','ปัญหา','ผิด','ล่าช้า','ขาด','สูญเสีย','ไม่ครบ','ผิดปกติ','ต้องระวัง'],action=['ต้อง','ดำเนินการ','ติดตาม','แก้ไข','ส่ง','ตรวจสอบ','อนุมัติ','ภายใน'],keys=tokens(topic).filter(x=>!['สรุป','ค้นหา','ข้อมูล','สำคัญ','ไฟล์','จาก'].includes(x));let pool=segments.map((s,i)=>({s,i,score:keys.reduce((n,k)=>n+(s.text.toLowerCase().includes(k)?3:0),0)}));if(lower.includes('ความเสี่ยง'))pool.forEach(x=>x.score+=risk.reduce((n,k)=>n+(x.s.text.includes(k)?2:0),0));if(lower.includes('ดำเนินการ'))pool.forEach(x=>x.score+=action.reduce((n,k)=>n+(x.s.text.includes(k)?2:0),0));if(lower.includes('ตัวเลข'))pool.forEach(x=>x.score+=(x.s.text.match(/[\d,.%฿]+/g)||[]).length);pool.sort((a,b)=>b.score-a.score||a.i-b.i);const chosen=pool.filter(x=>x.score>0).slice(0,6);if(!chosen.length)chosen.push(...pool.slice(0,5));return chosen.map(({s})=>{let text=s.text.slice(0,500);if(lower.includes('ตัวเลข')){const nums=s.text.match(/.{0,55}[\d][\d,.%฿]*.{0,55}/g);if(nums?.length)text=nums.slice(0,3).join(' · ');}return{text,citations:[{label:s.label,page:s.page||0}]};});}
  window.fileLibrarySearch=search;
  window.fileLibrarySetSource=v=>{state.source=v;const sel=document.getElementById('filelib-source');if(sel)sel.value=v;search();};
  window.fileLibrarySelect=async key=>{state.selected=key;state.extraction=null;state.analysis=null;renderList();renderPanel();const x=selectedItem();if(x?.extraction_status==='ready'){const r=await SB.rpc('get_file_library_extraction',{p_source_kind:x.source_kind,p_source_file_id:x.source_file_id});if(!r.error&&r.data){state.extraction=r.data;renderExtraction();}}};
  window.fileLibraryOpenFile=async(download=false,page=0)=>{const x=selectedItem();if(!x)return;try{let url=await signedUrl(x,download);if(page&&extOf(x)==='pdf')url+=`#page=${page}`;window.open(url,'_blank','noopener');}catch(e){toast('เปิดไฟล์ไม่สำเร็จ · '+(e.message||e),'info');}};
  window.fileLibraryOpenWork=()=>{const x=selectedItem();if(!x)return;if(x.source_kind==='activity'&&typeof openActivityEntry==='function'){openActivityEntry(Number(x.work_id));return;}if(x.source_kind==='graphic'&&typeof openGraphicJob==='function'){go('graphic');setTimeout(()=>openGraphicJob(x.work_id),100);return;}const t=TASKS.find(v=>v.dbId===x.work_id);if(t){openTask(t.id);return;}F.q=`T-${x.work_no}`;go('board');};
  window.fileLibraryExtract=async()=>{const x=selectedItem();if(!x)return;const host=document.getElementById('filelib-extracted');if(host)host.innerHTML='<div class="filelib-result">กำลังอ่านไฟล์นี้ตามคำสั่งของคุณ…</div>';try{const segments=await extractItem(x);if(!segments.length)throw new Error('ไม่พบข้อความที่อ่านได้');const r=await SB.rpc('save_file_library_extraction',{p_source_kind:x.source_kind,p_source_file_id:x.source_file_id,p_segments:segments});if(r.error)throw r.error;state.extraction={segments};x.extraction_status='ready';x.extracted_at=new Date().toISOString();renderList();renderExtraction();toast('ดึงข้อความจากไฟล์นี้แล้ว');}catch(e){if(host)host.innerHTML=`<div class="filelib-result" style="color:var(--red)">${esc(e.message||e)}</div>`;toast('ดึงข้อความไม่สำเร็จ · '+(e.message||e),'info');}};
  window.fileLibraryPreset=v=>{const el=document.getElementById('filelib-topic');if(el&&v)el.value=v;};
  window.fileLibraryAnalyze=async()=>{const x=selectedItem(),topic=document.getElementById('filelib-topic')?.value.trim();if(!x||!topic){toast('กรุณาระบุหัวข้อที่ต้องการวิเคราะห์','info');return;}if(!state.extraction){const r=await SB.rpc('get_file_library_extraction',{p_source_kind:x.source_kind,p_source_file_id:x.source_file_id});if(r.error||!r.data?.segments){toast('กรุณากดดึงข้อความจากไฟล์ก่อน','info');return;}state.extraction=r.data;}const items=analyzeSegments(topic,state.extraction.segments||[]);if(!items.length){toast('ไม่พบข้อความที่ใช้ตอบหัวข้อนี้','info');return;}state.analysis={topic,items};renderAnalysis();const answer=items.map(v=>v.text).join('\n\n'),citations=items.flatMap(v=>v.citations);const saved=await SB.rpc('save_file_library_analysis',{p_source_kind:x.source_kind,p_source_file_id:x.source_file_id,p_topic:topic,p_answer:answer,p_citations:citations});if(saved.error)toast('แสดงผลแล้ว แต่บันทึกประวัติไม่สำเร็จ · '+saved.error.message,'info');};
  RENDER.files=async()=>{renderShell();await search();};
})();
